const triples = {
  "darwin-arm64": "@livekit/local-inference-darwin-arm64",
  "darwin-x64":   "@livekit/local-inference-darwin-x64",
  "linux-x64":    "@livekit/local-inference-linux-x64-gnu",
  "linux-arm64":  "@livekit/local-inference-linux-arm64-gnu",
  "win32-x64":    "@livekit/local-inference-win32-x64-msvc",
};

const key = `${process.platform}-${process.arch}`;
const subpkg = triples[key];
if (!subpkg) {
  throw new Error(
    `@livekit/local-inference: no prebuilt binary for ${key}. ` +
    `Supported: ${Object.keys(triples).join(", ")}.`
  );
}

let binding;
try {
  binding = require(subpkg);
} catch (subErr) {
  // Fall back to a locally-built .node (build/Release or prebuilds/)
  // so `pnpm link` / local checkouts work without the sub-package.
  try {
    binding = require("node-gyp-build")(__dirname);
  } catch {
    const err = new Error(
      `@livekit/local-inference: failed to load ${subpkg}. ` +
      `Re-run \`npm install\` (or \`pnpm install\`) so the optional ` +
      `platform dependency for ${key} is fetched.`
    );
    err.cause = subErr;
    throw err;
  }
}

module.exports = {
  predict: binding.predict,
  createVad: binding.createVad,
  initEot: binding.initEot,
  initVad: binding.initVad,
  VAD_WINDOW_SAMPLES: binding.VAD_WINDOW_SAMPLES,
};
